using Azure;
using Azure.Search.Documents;
using Azure.Search.Documents.Models;

var endpoint = new Uri("https://my-search-service.search.windows.net/");
var credential = new AzureKeyCredential("my-admin-key");
var client = new SearchClient(endpoint, "documents-index", credential);

// Generate embedding for the query (using Azure OpenAI)
float[] queryEmbedding = await GetEmbeddingAsync("How do I deploy to Azure?");

var options = new SearchOptions
{
    VectorSearch = new VectorSearchOptions
    {
        Queries =
        {
            new RawVectorQuery
            {
                Vector = queryEmbedding,
                KNearestNeighborsCount = 5,
                Fields = { "contentVector" }
            }
        }
    },
    Size = 5
};

SearchResults<SearchDocument> results = await client.SearchAsync<SearchDocument>(
    "deployment azure tutorial", options);

await foreach (SearchResult<SearchDocument> result in results.Value.GetResultsAsync())
{
    Console.WriteLine(result.Document["title"] + " (score: " + result.Score + ")");
}
